import{_ as o,o as a,c as r,a2 as p}from"./chunks/framework.CqGPl1zp.js";const t="/newx-doc/assets/%E6%B5%8B%E8%AF%95%E5%B0%8F%E7%A8%8B%E5%BA%8F-%E5%AF%86%E9%92%A5.BGPvnFge.png",i="/newx-doc/assets/%E5%90%8E%E7%AB%AF%E9%85%8D%E7%BD%AE%E9%A1%B9.DkMk539P.png",n="/newx-doc/assets/%E9%85%8D%E7%BD%AE%E5%B0%8F%E7%A8%8B%E5%BA%8F.By3fBUy4.png",l="/newx-doc/assets/%E5%BE%AE%E4%BF%A1%E5%BC%80%E5%8F%91%E8%80%85%E5%B7%A5%E5%85%B7%E8%BF%90%E8%A1%8C.m0Jtngxo.png",c="/newx-doc/assets/%E5%95%86%E5%9F%8E%E9%A6%96%E9%A1%B5.Cspt9jB8.png",s="/newx-doc/assets/%E6%B7%BB%E5%8A%A0%E5%BC%80%E5%8F%91%E8%80%85%E6%88%90%E5%91%98.C049BnHc.png",d="/newx-doc/assets/%E7%99%BB%E5%BD%95%E5%BC%B9%E7%AA%97.BIXRTNkL.png",m="/newx-doc/assets/%E6%8E%88%E6%9D%83%E4%BF%A1%E6%81%AF.DUMwMP0k.png",x=JSON.parse('{"title":"微信小程序登录","description":"","frontmatter":{},"headers":[],"relativePath":"member/weixin-lite-login.md","filePath":"member/weixin-lite-login.md","lastUpdated":null}'),h={name:"member/weixin-lite-login.md"};function E(u,e,_,g,B,A){return a(),r("div",null,[...e[0]||(e[0]=[p('<h1 id="微信小程序登录" tabindex="-1">微信小程序登录 <a class="header-anchor" href="#微信小程序登录" aria-label="Permalink to &quot;微信小程序登录&quot;">​</a></h1><p>前置阅读文章：</p><ul><li><a href="./../user-center">《用户体系》</a></li><li><a href="./../social-user">《三方登录》</a></li></ul><p>本文是 <a href="./../social-user">《三方登录》</a> 的延伸，讲解 <a href="https://github.com/yudaocode/yudao-mall-uniapp" target="_blank" rel="noreferrer"><code>yudao-mall-uniapp</code></a> 商城小程序如何实现微信 <strong>小程序</strong> 登录的功能。</p><h2 id="_1-小程序准备" tabindex="-1">1. 小程序准备 <a class="header-anchor" href="#_1-小程序准备" aria-label="Permalink to &quot;1. 小程序准备&quot;">​</a></h2><p>友情提示：</p><p>本文，我们以“测试小程序”举例子，方便大家操作，认证一个小程序太难了！！！</p><p>① 参考 <a href="https://developers.weixin.qq.com/miniprogram/dev/devtools/sandbox.html" target="_blank" rel="noreferrer">微信小程序测试号申请</a> 链接，申请一个测试小程序。</p><p>② 将 <code>AppID</code> 和 <code>AppSecret</code> 配置，设置到后端项目 <code>application-local.yaml</code> 的 <code>wx.miniapp</code> 配置项中。如下图所示：</p><p><img src="'+t+'" alt="测试小程序 - 密钥"></p><p><img src="'+i+'" alt=" 配置项"></p><p>③ 使用 HBuilder 打开 <code>yudao-mall-uniapp</code> 项目根目录的 <code>manifest.json</code> 文件，将微信小程序配置的 AppID 改成你自己的。如下图所示：</p><p><img src="'+n+'" alt="配置小程序"></p><h2 id="_2-代码实现" tabindex="-1">2. 代码实现 <a class="header-anchor" href="#_2-代码实现" aria-label="Permalink to &quot;2. 代码实现&quot;">​</a></h2><h3 id="_2-1-项目启动" tabindex="-1">2.1 项目启动 <a class="header-anchor" href="#_2-1-项目启动" aria-label="Permalink to &quot;2.1 项目启动&quot;">​</a></h3><p>① 下载 <a href="https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html" target="_blank" rel="noreferrer">微信开发者工具</a> ，并进行安装。</p><p>② 参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档的「2. uni-app 商城移动端」小节，将 <code>yudao-mall-uniapp</code> 商城项目跑起来。</p><p>不过要注意，HBuilder 运行时，选择「微信开发者工具」。如下图所示：</p><p><img src="'+l+'" alt="微信开发者工具运行"></p><p>③ 运行成功后，可以在微信开发者工具中，看到如下界面：</p><p><img src="'+c+'" alt="商城首页"></p><p>如果请求报错，注意勾选下“不校验合法域名、web-view（业务域名）”选项。</p><p>补充说明：如果你是正式的小程序，需要额外看下这部分的内容：</p><p>① 在小程序的 [管理 -&gt; 成员管理] 菜单，添加自己微信号为开发者。如下图所示：</p><p><img src="'+s+'" alt="添加开发者成员"></p><p>否则，使用 HBuilder 运行时，会报“[微信小程序开发者工具] [error] Error: Fail to open IDE”！</p><h3 id="_2-2-登录流程" tabindex="-1">2.2 登录流程 <a class="header-anchor" href="#_2-2-登录流程" aria-label="Permalink to &quot;2.2 登录流程&quot;">​</a></h3><p>① 点击「我的」菜单，再随便点个子菜单，例如说“拼团订单”，触发弹出“登录窗口”，对应前端 <code>sheep/components/s-auth-modal/s-auth-modal.vue</code> 组件。如下图所示：</p><p><img src="'+d+'" alt="登录弹窗"></p><p>有两种登录方式：<a href="https://developers.weixin.qq.com/miniprogram/dev/framework/open-ability/login.html" target="_blank" rel="noreferrer">微信小程序登录</a> 、<a href="https://developers.weixin.qq.com/miniprogram/dev/framework/open-ability/getPhoneNumber.html" target="_blank" rel="noreferrer">手机快速验证登录</a></p><p>② 方式一：【微信小程序登录】点击「微信登录」图标，触发微信小程序登录。前端核心实现都在 <code>sheep/platform/provider/wechat/miniProgram.js</code> 的 <code>#login(...)</code> 方法中。</p><p>此时，前端调用微信小程序获得“临时” <code>code</code> 授权码参数，之后调用后端的 AppAuthController 的 <code>#socialLogin(...)</code> 方法，进行登录逻辑。注意：</p><ul><li>情况一：如果该微信用户已经绑定会员用户，则直接进行登录</li><li>情况二：如果该微信用户没有绑定会员用户，则会自动创建一个会员用户，并进行登录。下次重新登录时，就走【情况一】的逻辑。</li></ul><p>之后，会弹出“授权信息”窗口，对应 <code>sheep/components/s-auth-modal/components/mp-authorization.vue</code> 组件。如下图所示：</p><p><img src="'+m+'" alt="授权信息"></p><ul><li>注意：该弹窗仅仅用于微信小程序的昵称、头像的获取，用户实际已经登录成功了。</li></ul><p>③ 方式二：【手机快速验证登录】点击「快捷登录」按钮，触发一键登录。前端核心实现都在 <code>sheep/platform/provider/wechat/miniProgram.js</code> 的 <code>#mobileLogin(...)</code> 方法中。</p><p>此时，前端调用用微信小程序获得“临时” <code>code</code> 授权参数 + “手机” <code>code</code> 授权参数，之后调用后端的 AppAuthController 的 <code>#weixinMiniAppLogin(...)</code> 方法，进行登录逻辑。注意：</p><ul><li>情况一：如果该手机已经注册用户，则直接进行登录</li><li>情况二：如果该手机没有注册用户，则会自动创建一个会员用户，并进行登录。下次重新登录时，就走【情况一】的逻辑。</li></ul><p>为什么此时要获得“临时” <code>code</code> 授权参数呢？主要想把微信小程序的 <code>openid</code> 和用户绑定起来，毕竟方式二【手机快速验证登录】是需要收费的！！！</p>',40)])])}const w=o(h,[["render",E]]);export{x as __pageData,w as default};
